 /* ===== INTRO MODE (deck slide 2): close-up of the tired interceptor, then the friendly handover. No API calls. ===== */
 const IT1=10,IEND=IT1+TKL; let IS=null;
 function introReset(){const R=rng(11);IS={t:0,R,tr:[],caught:0,missed:0,acc:0,sting:false,huffs:[]};for(let i=0;i<14;i++)IS.tr.push(introItem(R,R()*W))}
 function introItem(R,x){return {x:x==null?-8:x,y:118+R()*52,v:34+R()*30,c:PCOL[(R()*5)|0],w:2+((R()*3)|0),h:2+((R()*2)|0),b:R()*6}}
