  if(t<IT1){txt('CAUGHT '+s.caught,8,190,NES.green,8);txt('GOT AWAY '+s.missed,248,190,NES.red,8,'right');txt(t<3?'MEET THE INTERCEPTOR':'CHASE. MISS. HUFF. REPEAT.',128,206,NES.white,6,'center')}
